alter table public.surat_perintah disable trigger trg_surat_perintah_before_write;

insert into public.surat_perintah (
  nomor_agenda, nomor_lengkap, jenis_kegiatan_id, perihal, pertimbangan, lokasi,
  tanggal_mulai, tanggal_selesai, jam_apel,
  status, disusun_oleh, disetujui_oleh, disetujui_pada
)
select
  x.nomor_agenda, x.nomor_lengkap, jk.id, x.perihal,
  'bahwa dalam rangka ' || lower(left(x.perihal,1)) || substring(x.perihal from 2) || ', maka dipandang perlu mengeluarkan surat perintah ini.',
  x.lokasi, x.tanggal_mulai::date, x.tanggal_selesai::date, nullif(x.jam_apel,'')::time,
  'TERBIT'::status_surat_perintah,
  (select id from public.pengguna where nrp = '87121335'),
  (select id from public.pengguna where nrp = '76010326'),
  x.tanggal_mulai::date::timestamptz
from jsonb_to_recordset('[{"nomor_agenda":2086,"nomor_lengkap":"SPRIN/2086/IX/PAM.3.3./2026","jenis_kegiatan_nama":"PENGAMANAN KEGIATAN LAINNYA","perihal":"Melaksanakan Kegiatan Latihan Simulasi Sispamkota Rayon Bandung Raya Penanganan Tindakan Anarkis dalam Aksi Unjuk Rasa di Wilayah Hukum Polda Jabar","lokasi":"Lapangan Tegalega Jalan Otto Iskandar Dinata, Kelurahan Karanganyar, Kecamatan Astanaanyar","tanggal_mulai":"2026-09-09","tanggal_selesai":"2026-09-09","jam_apel":"06:00"},{"nomor_agenda":2094,"nomor_lengkap":"SPRIN/2094/IX/PAM.1.3.2./2026","jenis_kegiatan_nama":"KEGIATAN RUTIN YANG DITINGKATKAN","perihal":"Kegiatan Rutin yang Ditingkatkan (Patroli dan Razia Skala Besar) di Wilayah Hukum Polres Cimahi","lokasi":"Halaman Polres Cimahi","tanggal_mulai":"2026-09-09","tanggal_selesai":"2026-09-09","jam_apel":"21:00"},{"nomor_agenda":2099,"nomor_lengkap":"SPRIN/2099/IX/PAM.1.3.2./2026","jenis_kegiatan_nama":"KEGIATAN RUTIN YANG DITINGKATKAN","perihal":"Kegiatan Rutin yang Ditingkatkan (Patroli dan Razia Skala Besar) di Wilayah Hukum Polres Cimahi","lokasi":"Lapang Apel Polres Cimahi","tanggal_mulai":"2026-09-11","tanggal_selesai":"2026-09-11","jam_apel":"21:00"},{"nomor_agenda":2104,"nomor_lengkap":"SPRIN/2104/IX/PAM.1.3.2./2026","jenis_kegiatan_nama":"KEGIATAN RUTIN YANG DITINGKATKAN","perihal":"Kegiatan Rutin yang Ditingkatkan (Patroli dan Razia Skala Besar) di Wilayah Hukum Polres Cimahi","lokasi":"Lapangan Apel Polres Cimahi","tanggal_mulai":"2026-09-12","tanggal_selesai":"2026-09-12","jam_apel":"21:00"},{"nomor_agenda":2096,"nomor_lengkap":"SPRIN/2096/IX/PAM.3.2./2026","jenis_kegiatan_nama":"PENGAMANAN UNJUK RASA","perihal":"Pengamanan Pemberangkatan Massa Aksi Unras SP/SB dari Wilayah Hukum Polres Cimahi ke Kantor DPRD Provinsi Jawa Barat","lokasi":"Titik Plotting masing-masing","tanggal_mulai":"2026-09-10","tanggal_selesai":"2026-09-10","jam_apel":"07:00"},{"nomor_agenda":2100,"nomor_lengkap":"SPRIN/2100/IX/PAM.3.3./2026","jenis_kegiatan_nama":"PENGAMANAN