  nomor_agenda int, nomor_lengkap text, jenis_kegiatan_nama text, perihal text,
  lokasi text, tanggal_mulai text, tanggal_selesai text, jam_apel text
)
join public.jenis_kegiatan jk on jk.nama = x.jenis_kegiatan_nama
where not exists (select 1 from public.surat_perintah sp where sp.nomor_lengkap = x.nomor_lengkap);

