insert into public.personel_non_kuatpers (nama, pangkat, nrp, jabatan_asal, keterangan, diinput_oleh)
select x.nama, x.pangkat, x.nrp, x.jabatan_asal, x.keterangan::keterangan_non_kuatpers,
  (select id from public.pengguna where nrp = '87121335')
from jsonb_to_recordset('[{"nrp":"75061111","nama":"KARTONO GUMILAR S.IP., M.H.","pangkat":"KOMPOL","jabatan_asal":"KAPOLSEK CIMAHI SELATAN","keterangan":"LAINNYA"},{"nrp":"83040883","nama":"H. HERI HERMANSYAH","pangkat":"AIPTU","jabatan_asal":"SAT LANTAS","keterangan":"LAINNYA"},{"nrp":"71110087","nama":"BAMBANG HARYONO","pangkat":"AKP","jabatan_asal":"KAPOLSEK LEMBANG","keterangan":"LAINNYA"},{"nrp":"88050368","nama":"ARIF JABAR MALIK","pangkat":"BRIPKA","jabatan_asal":"POLSEK CIKALONG WETAN","keterangan":"LAINNYA"},{"nrp":"82010952","nama":"M TONI AZHARI","pangkat":"AIPDA","jabatan_asal":"POLSEK MARGAASIH","keterangan":"LAINNYA"},{"nrp":"89060528","nama":"GANYAN ISMANTO","pangkat":"BRIPKA","jabatan_asal":"POLSEK MARGAASIH","keterangan":"LAINNYA"},{"nrp":"84080454","nama":"TAUFIK NUGRAHA, S.H","pangkat":"IPDA","jabatan_asal":"PAMA POLRES CIMAHI","keterangan":"LAINNYA"},{"nrp":"94090102","nama":"GARIZ LUIS MA''LUF, S.H., M.H","pangkat":"AKP","jabatan_asal":"PAMA POLRES CIMAHI","keterangan":"LAINNYA"},{"nrp":"90060182","nama":"AWALUDIN ABDUL MALIK, S.E","pangkat":"IPDA","jabatan_asal":"PAMA POLRES CIMAHI","keterangan":"LAINNYA"}]'::jsonb) as x(nrp text, nama text, pangkat text, jabatan_asal text, keterangan text)
where not exists (select 1 from public.personel_non_kuatpers where nrp = x.nrp);


insert into public.sprin_personel (sprin_kelompok_id, pengguna_id, nomor_urut_keseluruhan, nomor_urut_kelompok, jabatan_operasional)
