  (select count(*) from public.sprin_kelompok sk join public.surat_perintah sp on sp.id=sk.surat_perintah_id where sp.nomor_lengkap in ('SPRIN/2086/IX/PAM.3.3./2026','SPRIN/2094/IX/PAM.1.3.2./2026','SPRIN/2099/IX/PAM.1.3.2./2026','SPRIN/2104/IX/PAM.1.3.2./2026','SPRIN/2096/IX/PAM.3.2./2026','SPRIN/2100/IX/PAM.3.3./2026','SPRIN/2103/IX/PAM.3.3./2026','SPRIN/2098/IX/PAM.3.3./2026','SPRIN/2110/IX/PAM.3.2./2026')) as kelompok_masuk,
  (select count(*) from public.sprin_personel spr join public.sprin_kelompok sk on sk.id=spr.sprin_kelompok_id join public.surat_perintah sp on sp.id=sk.surat_perintah_id where sp.nomor_lengkap in ('SPRIN/2086/IX/PAM.3.3./2026','SPRIN/2094/IX/PAM.1.3.2./2026','SPRIN/2099/IX/PAM.1.3.2./2026','SPRIN/2104/IX/PAM.1.3.2./2026','SPRIN/2096/IX/PAM.3.2./2026','SPRIN/2100/IX/PAM.3.3./2026','SPRIN/2103/IX/PAM.3.3./2026','SPRIN/2098/IX/PAM.3.3./2026','SPRIN/2110/IX/PAM.3.2./2026')) as personel_masuk;
